import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

/**
 * #625 — skill indexes written by ANOTHER harness that went stale.
 *
 * Four repos of the workspace carry a checked-in `.atl/skill-registry.md`: an
 * index generated by gentle-ai (`.atl` = Agent Teams Lite, its archived
 * predecessor). Measured: 22, 27, 21 and 48 indexed skills, and **zero** of
 * those paths exist on this machine — they are absolute paths of the laptop
 * that generated them. The files froze between 2026-06 and 2026-07.
 *
 * Why navori says anything at all about a file it does not own: the index
 * presents itself as authoritative ("Delegator use only. Any agent that
 * launches subagents reads it to select relevant skills, then passes exact
 * `SKILL.md` paths"). An agent that greps the repo for skills finds it and gets
 * dead paths, with nothing in the file admitting it is stale. That is garbage
 * shaped like documentation, which is worse than no documentation.
 *
 * The scope is deliberately DETECT AND REPORT, never touch: `.atl/` belongs to
 * another tool and navori does not write outside its own territory. It is also
 * not an interop problem — navori never reads or writes `.atl/` (verified: zero
 * hits for `gentle|\.atl` across `packages/**\/*.ts`).
 *
 * The no-false-positive rule is the whole design: an index is only reported
 * when it indexes something AND not a single one of those paths resolves. A
 * developer actively using gentle-ai on this machine has live paths and hears
 * nothing.
 */

/** A known foreign index: where it lives and how to read the paths out of it. */
interface KnownIndex {
  /** Repo-relative location, as its producer writes it. */
  relPath: string;
  /** Producer name, for the message. */
  producer: string;
  /**
   * Absolute `SKILL.md` paths the index declares. They sit inside a markdown
   * table, wrapped in backticks — the backticks matter: without them the
   * pattern also swallows the surrounding table cell.
   */
  pathPattern: RegExp;
  /** The self-declared refresh date, when the format carries one. */
  datePattern: RegExp;
}

const KNOWN_INDEXES: readonly KnownIndex[] = [
  {
    relPath: ".atl/skill-registry.md",
    producer: "gentle-ai (Agent Teams Lite)",
    pathPattern: /`(\/[^`\n]+SKILL\.md)`/g,
    datePattern: /Last updated:\s*(\S+)/,
  },
];

export interface ForeignSkillIndex {
  /** Repo-relative path of the offending file. */
  path: string;
  /** The harness that wrote it. */
  producer: string;
  /** How many skill paths it declares. */
  indexed: number;
  /** The self-declared refresh date, or null when the file carries none. */
  frozenAt: string | null;
}

/**
 * Foreign skill indexes in `cwd` whose contents are entirely dead.
 *
 * Returns an empty array both when no such file exists and when the one that
 * does still resolves — the caller renders nothing in either case, so a repo
 * with a healthy second harness stays quiet.
 */
export function scanForeignSkillIndexes(cwd: string): ForeignSkillIndex[] {
  const found: ForeignSkillIndex[] = [];
  for (const known of KNOWN_INDEXES) {
    const abs = join(cwd, known.relPath);
    if (!existsSync(abs)) continue;
    let text: string;
    try {
      text = readFileSync(abs, "utf-8");
    } catch {
      // Unreadable is not a finding: doctor never fails on what it cannot read.
      continue;
    }
    const paths = [...text.matchAll(known.pathPattern)]
      .map((m) => m[1]?.trim())
      .filter((p): p is string => p !== undefined && p.length > 0);
    // An index with no entries says nothing about staleness, and one with a
    // single live path belongs to a tool someone is actually using.
    if (paths.length === 0) continue;
    if (paths.some((p) => existsSync(p))) continue;
    found.push({
      path: known.relPath,
      producer: known.producer,
      indexed: paths.length,
      frozenAt: known.datePattern.exec(text)?.[1] ?? null,
    });
  }
  return found;
}
